<script setup lang="ts">
import { computed, ref } from 'vue'
import source from './seasonality.fixture.json'

const readings: Record<string, number> = source
const months = ['January','February','March','April','May','June','July','August','September','October','November','December']
const weekdays = ['M','T','W','T','F','S','S']
const scoreNames = ['No seasonal tendency','One seasonal tendency','Two overlapping tendencies','Three overlapping tendencies']
const selected = ref('2026-10-27')
const view = ref<'year' | 'month'>('month')
const tab = ref<'calendar' | 'history' | 'data' | 'methodology'>('calendar')
const focusMonth = ref(9)
const scoreFilter = ref('all')
const tableMonth = ref('all')
const tableScore = ref('all')
const tableQuery = ref('')
const selectedScore = computed(() => readings[selected.value])
const entries = Object.entries(readings).sort(([left], [right]) => left.localeCompare(right))
const overlapCount = entries.filter(([, score]) => score >= 2).length
const filteredEntries = computed(() => entries.filter(([date, score]) => {
  const month = Number(date.slice(5, 7)) - 1
  const query = tableQuery.value.trim().toLowerCase()
  return (tableMonth.value === 'all' || month === Number(tableMonth.value)) && (tableScore.value === 'all' || score === Number(tableScore.value)) && (!query || `${date} ${dateLabel(date)} ${scoreNames[score]}`.toLowerCase().includes(query))
}))
function dateLabel(date: string) { const [, month, day] = date.split('-').map(Number); return `${months[month - 1]} ${day}, 2026` }
function weekday(date: string) { return new Date(`${date}T12:00:00Z`).toLocaleDateString('en-US', { weekday: 'long', timeZone: 'UTC' }) }
function monthDates(month: number) {
  const first = (new Date(Date.UTC(2026, month, 1)).getUTCDay() + 6) % 7
  const days = new Date(Date.UTC(2026, month + 1, 0)).getUTCDate()
  return [...Array.from({ length: first }, () => null), ...Array.from({ length: days }, (_, index) => `2026-${String(month + 1).padStart(2, '0')}-${String(index + 1).padStart(2, '0')}`)]
}
function isWeekend(date: string) { const day = new Date(`${date}T12:00:00Z`).getUTCDay(); return day === 0 || day === 6 }
function scoreClass(score?: number) { return score === 0 ? 'bg-[var(--app-negative)]/20 text-[var(--app-negative)] border-[var(--app-negative)]/20' : score === 1 ? 'bg-[var(--app-primary-soft)] text-[var(--app-text-secondary)] border-[var(--app-border)]' : score === 2 ? 'bg-[var(--app-positive)]/20 text-[var(--app-positive)] border-[var(--app-positive)]/20' : score === 3 ? 'bg-[var(--app-positive)] text-white border-[var(--app-positive)]' : 'bg-[var(--app-surface-muted)] text-[var(--app-text-faint)] border-transparent' }
function selectDate(date: string, openCalendar = false) { selected.value = date; focusMonth.value = Number(date.slice(5, 7)) - 1; if (openCalendar) { tab.value = 'calendar'; view.value = 'month' } }
function jumpMonth(month: number) { focusMonth.value = month; view.value = 'month' }
const chartWidth = 1080, chartHeight = 280, chartLeft = 38, chartTop = 22, chartBottom = 244
const historyX = (date: string) => chartLeft + (Date.parse(`${date}T12:00:00Z`) - Date.UTC(2026, 0, 1)) / 86400000 / 365 * (chartWidth - chartLeft - 26)
const historyY = (score: number) => chartTop + (chartBottom - chartTop) * (1 - score / 4)
const methods = [
  ['Pre-holiday sessions','The two sessions immediately before an exchange holiday, using the calendar adjustments defined by the model.'],
  ['Turn of the month','The last trading day of the month and the first four trading days of the following month.'],
  ['November through May','November 1 through the third trading day in May.'],
  ['Presidential cycle','The 15-month period beginning October 1 two years before a presidential election and ending December 31 of the following year.'],
]
</script>

<template>
  <section class="space-y-4" data-testid="seasonality-calendar-content">
    <div class="grid gap-3 sm:grid-cols-2 2xl:grid-cols-4" aria-label="Seasonality summary">
      <article v-for="stat in [{label:'Calendar year',value:'2026',detail:'Daily seasonal index'},{label:'Selected date',value:dateLabel(selected).replace(', 2026',''),detail:`Index reading: ${selectedScore ?? '—'}`},{label:'Overlap threshold',value:'2+',detail:'Multiple seasonal conditions align'},{label:'Model inputs',value:'4',detail:'Tendencies defined in the methodology'}]" :key="stat.label" class="rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] p-4 shadow-sm"><p class="text-xs text-[var(--app-text-muted)]">{{ stat.label }}</p><strong class="mt-2 block text-2xl font-semibold" :class="stat.label === 'Calendar year' ? 'text-[var(--app-primary)]' : ''">{{ stat.value }}</strong><span class="mt-1 block text-[.6875rem] text-[var(--app-text-faint)]">{{ stat.detail }}</span></article>
    </div>
    <div class="flex gap-6 overflow-x-auto rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] px-5" role="tablist" aria-label="Seasonality views"><button v-for="item in [{key:'calendar',label:'Calendar'},{key:'history',label:'Index history'},{key:'data',label:'Data table'},{key:'methodology',label:'Methodology'}] as const" :key="item.key" type="button" role="tab" :aria-selected="tab === item.key" class="whitespace-nowrap border-b-2 py-3 text-xs font-semibold" :class="tab === item.key ? 'border-[var(--app-primary)] text-[var(--app-primary)]' : 'border-transparent text-[var(--app-text-muted)]'" @click="tab = item.key">{{ item.label }}</button></div>
    <div v-if="tab === 'calendar'" class="grid items-start gap-4 2xl:grid-cols-[minmax(0,1fr)_250px]">
      <section class="min-w-0 overflow-hidden rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] shadow-sm"><header class="flex flex-wrap items-center justify-between gap-3 border-b border-[var(--app-border)] px-5 py-4"><div><h2 class="font-semibold">2026 seasonality calendar</h2><p class="mt-1 text-xs text-[var(--app-text-muted)]">Choose a day to inspect its index reading.</p></div><div class="inline-flex rounded border border-[var(--app-border)] p-0.5"><button v-for="option in ['year','month'] as const" :key="option" type="button" class="rounded px-3 py-1.5 text-xs font-semibold capitalize" :class="view === option ? 'bg-[var(--app-primary-soft)] text-[var(--app-primary)]' : 'text-[var(--app-text-muted)]'" @click="view = option">{{ option }}</button></div></header><div class="flex flex-wrap items-center justify-between gap-3 border-b border-[var(--app-border)] px-5 py-3"><select v-model.number="focusMonth" aria-label="Choose month" class="rounded border border-[var(--app-border)] bg-[var(--app-surface)] px-3 py-2 text-xs" @change="view = 'month'"><option v-for="(month,index) in months" :key="month" :value="index">{{ month }} 2026</option></select><div class="flex items-center gap-1.5 text-[10px] text-[var(--app-text-muted)]"><span>Highlight score</span><button v-for="value in ['all','0','1','2','3']" :key="value" type="button" class="h-6 min-w-6 rounded border px-1.5" :class="scoreFilter === value ? 'border-[var(--app-primary)] bg-[var(--app-primary-soft)] text-[var(--app-primary)]' : 'border-[var(--app-border)] bg-[var(--app-surface-soft)]'" @click="scoreFilter = value">{{ value === 'all' ? 'All' : value }}</button></div></div>
        <div class="grid gap-5 p-5" :class="view === 'year' ? 'sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4' : 'grid-cols-1'"><section v-for="month in (view === 'year' ? months.map((_,index) => index) : [focusMonth])" :key="month" class="min-w-0"><div class="mb-2 flex justify-between"><button type="button" class="text-left text-xs font-semibold" :class="month === focusMonth ? 'text-[var(--app-primary)]' : ''" @click="jumpMonth(month)">{{ months[month] }}</button><span class="text-[10px] text-[var(--app-text-faint)]">2026</span></div><div class="grid grid-cols-7 gap-1"><span v-for="(day,index) in weekdays" :key="`${day}-${index}`" class="pb-1 text-center text-[9px] text-[var(--app-text-faint)]">{{ day }}</span></div><div class="grid grid-cols-7 gap-1"><template v-for="(date,index) in monthDates(month)" :key="`${month}-${index}`"><span v-if="date === null" /><button v-else type="button" :aria-label="`${dateLabel(date)}: ${readings[date] === undefined ? 'no reading shown' : `score ${readings[date]}`}`" :title="`${dateLabel(date)} · ${readings[date] === undefined ? 'No reading shown' : `Index ${readings[date]}`}`" :style="readings[date] === undefined && !isWeekend(date) ? { backgroundImage: 'repeating-linear-gradient(135deg, #f7f9fc, #f7f9fc 3px, #edf1f7 3px, #edf1f7 4px)' } : undefined" class="relative flex aspect-square min-w-0 items-center justify-center rounded border text-[10px] tabular-nums" :class="[readings[date] === undefined && isWeekend(date) ? 'border-transparent bg-transparent text-[var(--app-text-faint)]' : scoreClass(readings[date]), date === selected ? 'z-10 outline outline-2 outline-offset-1 outline-[var(--app-primary)]' : '', scoreFilter !== 'all' && String(readings[date]) !== scoreFilter ? 'opacity-25' : '', view === 'month' ? 'h-14 aspect-auto items-start justify-start p-2 text-xs sm:h-16' : '']" @click="selectDate(date)">{{ Number(date.slice(-2)) }}<em v-if="view === 'month' && readings[date] !== undefined" class="absolute bottom-1 right-2 text-xl not-italic font-semibold">{{ readings[date] }}</em></button></template></div></section></div><footer class="border-t border-[var(--app-border)] bg-[var(--app-surface-soft)] px-5 py-3 text-[10px] text-[var(--app-text-muted)]">Color shows the number of active seasonal tendencies. Dates without a reading have no available source value.</footer></section>
      <aside class="rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] p-5 shadow-sm"><p class="text-[10px] font-bold uppercase tracking-wider text-[var(--app-text-muted)]">Selected date</p><h2 class="mt-2 font-semibold">{{ dateLabel(selected) }}</h2><div class="mt-5 rounded-lg border border-[var(--app-border)] bg-[var(--app-surface-soft)] p-5 text-center"><p class="text-[10px] font-bold uppercase tracking-wider text-[var(--app-text-muted)]">Seasonality Index · 0–4 points</p><strong class="mt-2 block text-5xl" :class="selectedScore === undefined ? 'text-[var(--app-text-muted)]' : selectedScore >= 2 ? 'text-[var(--app-positive)]' : selectedScore === 0 ? 'text-[var(--app-negative)]' : 'text-[var(--app-text-secondary)]'">{{ selectedScore ?? '—' }}</strong><p class="mt-2 text-xs text-[var(--app-text-muted)]">{{ selectedScore === undefined ? 'No reading available' : scoreNames[selectedScore] }}</p></div><p class="mt-4 text-xs leading-5 text-[var(--app-text-muted)]">The index counts seasonal tendencies. It is not a forecast of the size of a market return.</p><div class="mt-5 border-t border-[var(--app-border)] pt-4"><p class="text-[10px] font-bold uppercase tracking-wider text-[var(--app-text-muted)]">How to read the score</p><div v-for="(text,index) in ['No tendency active','One tendency active','Two tendencies overlap','Three tendencies overlap']" :key="index" class="mt-2 flex items-center gap-2 text-xs text-[var(--app-text-muted)]"><b class="grid h-6 w-6 place-items-center rounded" :class="scoreClass(index)">{{ index }}</b>{{ text }}</div><button type="button" class="mt-4 w-full rounded border border-[var(--app-border)] bg-[var(--app-primary-soft)] px-3 py-2 text-xs font-semibold text-[var(--app-primary)]" @click="tab = 'methodology'">Read the methodology →</button></div></aside>
    </div>
    <section v-else-if="tab === 'history'" class="overflow-hidden rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)]"><header class="border-b border-[var(--app-border)] px-5 py-4"><h2 class="font-semibold">2026 Seasonality Index</h2><p class="mt-1 text-xs text-[var(--app-text-muted)]">{{ entries.length }} daily readings · {{ overlapCount }} days with overlapping tendencies</p></header><div class="p-5"><svg :viewBox="`0 0 ${chartWidth} ${chartHeight}`" class="min-h-[210px] w-full" role="img" aria-label="2026 daily Seasonality Index chart"><g v-for="score in [0,1,2,3,4]" :key="score"><line :x1="chartLeft" :x2="chartWidth - 26" :y1="historyY(score)" :y2="historyY(score)" stroke="var(--chart-grid)" /><text :x="chartLeft - 10" :y="historyY(score) + 4" text-anchor="end" fill="var(--app-text-muted)" font-size="11">{{ score }}</text></g><line :x1="chartLeft" :x2="chartWidth - 26" :y1="historyY(2)" :y2="historyY(2)" stroke="var(--app-positive)" stroke-dasharray="4 4" /><text :x="chartLeft + 5" :y="historyY(2) - 8" fill="var(--app-positive)" font-size="11">Overlap ≥2</text><g v-for="[date,score] in entries" :key="date"><circle v-if="score === 0" :cx="historyX(date)" :cy="historyY(0)" r="2" fill="var(--app-negative)"><title>{{ date }}: Seasonality Index {{ score }}</title></circle><rect v-else :x="historyX(date) - 1.2" :y="historyY(score)" width="2.4" :height="historyY(0) - historyY(score)" :fill="score >= 2 ? 'var(--app-positive)' : 'var(--app-primary)'" rx="1"><title>{{ date }}: Seasonality Index {{ score }}</title></rect></g><text v-for="(month,index) in months" :key="month" :x="historyX(`2026-${String(index + 1).padStart(2,'0')}-01`)" :y="chartHeight - 10" fill="var(--app-text-muted)" font-size="11" :text-anchor="index === 0 ? 'start' : 'middle'">{{ month.slice(0,3) }}</text></svg><div class="mt-4 rounded border border-[var(--app-border)] bg-[var(--app-primary-soft)] p-4 text-xs leading-5 text-[var(--app-text-secondary)]"><strong>Reading the chart</strong> · Each mark is one daily index reading. Hover a mark for its date and score. Dates without a reading are omitted; a zero score is shown on the baseline.</div></div></section>
    <section v-else-if="tab === 'data'" class="overflow-hidden rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)]"><header class="flex flex-wrap items-center justify-between gap-3 border-b border-[var(--app-border)] px-5 py-4"><div><h2 class="font-semibold">Daily seasonality readings</h2><p class="mt-1 text-xs text-[var(--app-text-muted)]">Filter by month or score; select a date to open it in the calendar.</p></div><span class="text-xs text-[var(--app-primary)]">{{ filteredEntries.length }} of {{ entries.length }} readings</span></header><div class="flex flex-wrap gap-3 border-b border-[var(--app-border)] p-4 text-xs"><label class="flex items-center gap-2">Month<select v-model="tableMonth" aria-label="Filter table by month" class="rounded border border-[var(--app-border)] bg-[var(--app-surface)] px-3 py-2"><option value="all">All months</option><option v-for="(month,index) in months" :key="month" :value="String(index)">{{ month }}</option></select></label><label class="flex items-center gap-2">Score<select v-model="tableScore" aria-label="Filter table by score" class="rounded border border-[var(--app-border)] bg-[var(--app-surface)] px-3 py-2"><option value="all">All scores</option><option v-for="score in [0,1,2,3]" :key="score" :value="String(score)">{{ score }}</option></select></label><input v-model="tableQuery" type="search" aria-label="Search daily seasonality readings" placeholder="Find a date…" class="min-w-[190px] flex-1 rounded border border-[var(--app-border)] bg-[var(--app-surface)] px-3 py-2" /></div><div class="max-h-[560px] overflow-auto"><table class="w-full min-w-[540px] text-left text-xs"><thead class="sticky top-0 bg-[var(--app-surface-muted)] text-[var(--app-text-muted)]"><tr><th v-for="heading in ['Date','Day','Score (points)','Active tendencies']" :key="heading" class="px-5 py-3">{{ heading }}</th></tr></thead><tbody><tr v-for="[date,score] in filteredEntries" :key="date" class="border-t border-[var(--app-border-muted)] hover:bg-[var(--app-surface-hover)]"><td class="px-5 py-3"><button type="button" class="text-[var(--app-primary)] hover:underline" @click="selectDate(date, true)">{{ dateLabel(date) }}</button></td><td class="px-5 py-3 text-[var(--app-text-muted)]">{{ weekday(date) }}</td><td class="px-5 py-3"><span class="grid h-7 w-8 place-items-center rounded font-bold" :class="scoreClass(score)">{{ score }}</span></td><td class="px-5 py-3 text-[var(--app-text-secondary)]">{{ scoreNames[score] }}</td></tr><tr v-if="!filteredEntries.length"><td colspan="4" class="p-8 text-center text-[var(--app-text-muted)]">No dates match these filters.</td></tr></tbody></table></div><footer class="border-t border-[var(--app-border)] bg-[var(--app-surface-soft)] px-5 py-3 text-xs text-[var(--app-text-muted)]">The table contains {{ entries.length }} available daily readings. Dates without a reading are omitted.</footer></section>
    <section v-else class="rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)]"><header class="border-b border-[var(--app-border)] px-5 py-4"><h2 class="font-semibold">Four seasonal tendencies</h2><p class="mt-1 text-xs text-[var(--app-text-muted)]">Each active condition contributes one point to the daily index.</p></header><div class="grid gap-4 p-5 md:grid-cols-2"><article v-for="([name,description],index) in methods" :key="name" class="rounded-md border border-[var(--app-border)] p-4"><h3 class="flex items-center gap-2 text-sm font-semibold"><span class="grid h-6 w-6 place-items-center rounded bg-[var(--app-primary-soft)] text-xs text-[var(--app-primary)]">{{ index + 1 }}</span>{{ name }}</h3><p class="mt-2 text-xs leading-5 text-[var(--app-text-muted)]">{{ description }}</p></article></div><div class="mx-5 mb-5 rounded border border-[var(--app-border)] bg-[var(--app-primary-soft)] p-4 text-xs leading-5 text-[var(--app-text-secondary)]"><strong>How the score works</strong> · One active tendency adds one point. A score of 2 or more means multiple seasonal tendencies overlap. The score describes calendar conditions, not the size of a future return.</div></section>
  </section>
</template>

